private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        if (v1 == null) {
            return false;
        }
        for (V v2 : vertices) {
            if (v1 == v2) {
                continue;
            }
            if (v2 == null) {
                return false;
            }
            if (graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

